# Round-2 patch of the report: starts from out/report_base_s7.json (the round-1 report produced by build_report.py) and applies the reviewer's fixes.
import json,re,copy,numpy as np,pandas as pd
O='/workspace/out/'
R0=json.load(open(O+'report_base_s7.json'))
res=R0['results']
s12=pd.read_csv(O+'s12_line_table.csv'); sp=json.load(open(O+'s12b_spatial_scatter.json')); spd={(x['line'],x['region'],x['ous']):x for x in sp}
vel=pd.read_csv(O+'s13_region_velocities.csv'); vsys=pd.read_csv(O+'s13_region_vsys.csv').set_index('region')
cat=pd.read_csv(O+'s14_source_catalogue.csv'); cb=pd.read_csv(O+'s14_common_beam.csv'); al=pd.read_csv(O+'s14_alpha.csv')
w11=json.load(open(O+'s11_wing_tests.json')); xo=json.load(open(O+'s15_crossous.json'))
geo=open(O+'s11b_geometry.txt').read()
A=lambda **k:[{'name':a,'value':str(b)} for a,b in k.items()]
ASS=A(systemic_velocity='region-specific line centres (out/s13_region_vsys.csv): N 2792+-19, S 2721+-21 km/s radio-LSRK; blended low-resolution lines 2780+-5; N-S midpoint 2756+-15',
      noise='per-channel rms from line-free channels of the same spectrum with lag-1 inflation; matched-filter errors additionally checked against the empirical scatter of the same template slid over line-free channels (includes baseline structure) and, for tentative lines, against the spatial scatter of the matched amplitude over the field',
      flux_scale='added in quadrature where stated: 5% Band 6, 10% Band 5 and 7 (ALMA nominal), plus 5-10% primary-beam term for pb<0.9 (12 m Gaussian model, FWHM 1.13 lambda/D, not measured); cross-OUS comparisons are image-plane only')
def add(q,v,c,e,target=None,unc=None,unit=None,ass=None): res.append(dict(quantity=q,target=target,value=v,uncertainty=unc,unit=unit,assumptions=ass or ASS,confidence=c,evidence=e))
drop=lambda pre: [x for x in res if not x['quantity'].startswith(pre)]
# ---- 1. patch all round-1 'Line properties' entries: 1G validity flag + flux-scale/pb term
CAL={'Xb55':.10,'Xb47':.10,'Xb4f':.05,'Xb4d':.05,'Xb4b':.05}
for x in res:
    if x['quantity']=='Line properties (see value)':
        m=re.search(r'FWHM=[^,]*, chi2r=([0-9.]+);',x['value']); ous=re.search(r'\((Xb\w+),',x['target']).group(1)
        if m and float(m.group(1))>2.0: x['value']='[1G PARAMETERS INVALID: chi2r=%s>>1, double-horned/blended profile: do NOT quote 1G FWHM/centroid as line width; use integrated I and 2G] '%m.group(1)+x['value']
        x['uncertainty']='formal fit errors in text; add flux scale %d%% (and 5-10%% pb term at E1/E2/W, pb 0.7-0.8 in B6) in quadrature for absolute fluxes; ratios inside one OUS/beam are insensitive to it'%(CAL[ous]*100)
        x['assumptions']=ASS
# ---- 2. replace systemic velocity
res[:]=[x for x in res if not x['quantity'].startswith('Systemic velocity')]
vs=lambda r:f"{vsys.loc[r,'v_mid_mean']:.0f}+-{max(vsys.loc[r,'v_mid_std'],5):.0f}"
add('Systemic (line-centre) velocities per region from HCO+/HCN 3-2 (1" and 0.25" beams)',
    'half-maximum midpoints, mean of 4 line/array estimates (km/s radio-LSRK): '+'; '.join(f"{r} {vs(r)} (dv vs 2780: {vsys.loc[r,'dv_vs_2780']:+.0f}, FWHM_hm {vsys.loc[r,'fwhm_mean']:.0f})" for r in ('N','S','Bridge','E1','E2','W','Sblue'))+
    f". N-S velocity offset = {vsys.loc['N','v_mid_mean']-vsys.loc['S','v_mid_mean']:+.0f}+-{np.hypot(vsys.loc['N','v_mid_std'],vsys.loc['S','v_mid_std']):.0f} km/s (N redshifted); midpoint of the two nuclei {0.5*(vsys.loc['N','v_mid_mean']+vsys.loc['S','v_mid_mean']):.0f}+-15 km/s ~ the task's nominal 2750; the single 2780+-5 km/s of round 1 is the flux-weighted centre of the blended low-resolution lines (N and S within one beam) and is not a systemic velocity of either nucleus. Line identifications and weak-line windows are made per region with these centres (templates in out/s12_line_table.csv: win_lo/win_hi)",
    'high','scripts/s13_region_velocities.py -> out/s13_region_velocities.csv, s13_region_vsys.csv',target='regions',unc='+-5 km/s (statistical, per estimate); +-10-20 km/s between estimates (profile asymmetry/beam mixing; N and S 1G centroids invalid, chi2r 2-20)',unit='km/s')
# ---- 3. wing reality tests
add('S-nucleus blue wing and Sblue blob (-450..-150 km/s): reality tests (dirty-beam/sidelobe, empirical noise, independent array)',
    "REAL (high confidence for existence; flux is a lower limit). (i) Empirical noise: beam-aperture blue-wing maps vs line-free pseudo-wing maps (-900..-600 and +450..+750 km/s, 13869-27738 pixels in 12\" box excluding 1.5\" around N,S): Xb4d HCO+ 3-2 Sblue peak 0.245 Jy/beam km/s = 13.8 sigma_MAD (sigma 0.0177), 0 of 13869 pseudo-wing pixels exceed it (max 0.083, 99.9th pct 0.066); HCN 0.346 = 19 sigma (0 of 27738); Xb4b (0.25\") 8.1 and 12.6 sigma. S nucleus blue wing 0.156 (HCO+) / 0.074 (HCN) at 8.8 sigma / 4.0 sigma (Xb4d). (ii) Sidelobe model: Sblue spectrum fitted as a*S+b*N on core channels (|v|<150): predicts blue-wing flux 0.009 (HCO+) / 0.022 (HCN) vs observed 0.182+-0.022 / 0.139+-0.021 Jy/beam km/s in Xb4d; wing/core ratio Sblue 0.22 vs S 0.035-0.055 and N <=0.01 (a dirty-beam response is channel independent so would copy the S/N profile shape); even a 10% sidelobe copy of S gives only 0.014 (HCO+). (iii) Independent array: Xb4b convolved to the Xb4d beam (flux-conserving kernel) gives at the Sblue peak 0.154 (HCO+) and 0.215 (HCN) Jy/beam km/s (Xb4d: 0.245/0.346 at its own peak, 0.181/0.142 at nominal position) and at S 0.114/0.087 (Xb4d 0.156/0.074): the same structure appears in two arrays with different dirty beams, with pseudo-wing field sigma 0.020/0.019. (iv) Red-side check: 0.25\" red wing at Sblue is -0.019+-0.012 (HCO+), i.e. the negative value flagged in round 1 is 1.6 sigma, not an artefact of structure. Caveat (Xb4b HCN only): the sidelobe model (0.012) is not distinguishable from the observed 0.016+-0.010 there. Beam-area scaling: a uniform source would be 12.1x brighter (Jy/beam) in the 0.94x0.74\" beam than the 0.25\" beam, so the 'ten times brighter at 0.94\"' is what an extended/clumpy structure predicts, not evidence for an artefact. Wings lie outside the clean mask (0-7% of wing channels) but the two independent dirty beams agree",
    'high','scripts/s11_wing_tests.py -> out/s11_wing_tests.txt/.json, s11_wing_maps.png',target='S nucleus, Sblue',unc='Sblue wing 0.18+-0.02 (stat) Jy/beam km/s HCO+ 3-2 Xb4d; +-5% flux scale; uncleaned => missing-flux/sidelobe systematic estimated <=0.01-0.02',unit='Jy/beam km/s')
add('Sblue blue-wing blob geometry (Xb4d, >4 sigma contiguous region around S)',
    "HCO+ 3-2: area 3.1 arcsec2, intensity-weighted centroid 1.8\" S of the S nucleus (offset -0.27\" E, -1.76\" N, PA 189 deg E of N), moment-based FWHM 2.3x0.7\" (beam 0.93x0.74\"), major axis PA 16 deg (nearly N-S, tilted toward SSW), integrated blue-wing flux ~0.58 Jy km/s; HCN 3-2: centroid 2.0\" S (-0.11,-1.98; PA 183), 1.8x0.8\", PA 14 deg, ~0.75 Jy km/s. So the blob is a ~2\" (~0.4 kpc at 40 Mpc, literature distance) elongated structure extending southward from the S nucleus, i.e. attached to S (not an isolated clump 3\" away as in the region definition 'Sblue', which sits at its southern end). It is aligned with the literature statement that the HCN/HCO+ outflow emanates from the southern nucleus (Michiyama+2018 abstract); the published outflow axis/position angle was NOT verified against the papers (only abstracts available), so the geometric consistency is qualitative",
    'medium','scripts/s11b_wing_geometry.py -> out/s11b_geometry.txt, s11_wing_maps.png',target='Sblue',unc='centroid +-0.1-0.2\" (beam/SNR), PA +-10 deg',unit='arcsec, deg')
# ---- 4. unified table: summary of strong lines per region (template-window integrated intensity with error budget)
def row(ous,line,reg,spec='ap'):
    q=s12[(s12.ous==ous)&(s12.line==line)&(s12.region==reg)&(s12.spec==spec)]; return q.iloc[0] if len(q) else None
parts=[]
for ous in ('Xb4b','Xb4d'):
    for line in ('HCN 3-2','HCO+ 3-2'):
        seg=[]
        for reg in ('N','S','Bridge','E1','E2','W','Sblue'):
            r=row(ous,line,reg)
            if r is None: continue
            seg.append(f"{reg} {r.I_T:.3f}+-{r.sig_stat:.3f}(stat)+-{np.hypot(r.sig_emp if r.sig_emp==r.sig_emp else 0,0):.3f}(emp)+-{r.sig_cal:.3f}(cal+pb)")
        parts.append(f"{ous} {line}: "+'; '.join(seg))
add('Unified per-line per-region integrated intensities, HCN & HCO+ 3-2, 0.25" and 0.94" beams (beam aperture, template window)',' | '.join(parts)+'. Convention: I_T = matched-filter amplitude x template integral, template = the region\'s own HCO+ 3-2 profile of the same OUS (window = >10% of peak around the region-specific centre), baseline from line-free channels, Jy/beam km/s; per-channel rms, peak, W_sum, K km/s, pb and blend flags for every line/region/OUS/spectrum-type (peak pixel and aperture) in the CSV',
    'high','scripts/s12_line_table.py -> out/s12_line_table.csv (494 rows: 21 lines x regions x OUS x pix/ap)',target='all regions',unc='stat from line-free rms (lag-1 inflated); emp = scatter of the template slid over line-free channels; cal = flux-scale (5%) + pb term in quadrature',unit='Jy/beam km/s')
for ous,lines in (('Xb55',['HCN 2-1','HCO+ 2-1']),('Xb47',['HCN 4-3','HCO+ 4-3']),('Xb4f',['HCN 3-2','HCO+ 3-2'])):
    seg=[]
    for line in lines:
        for reg in ('N','S','E1','E2','W','Sblue'):
            r=row(ous,line,reg)
            if r is None or r.blend_resp>0.5 and reg not in ('N','S'): continue
            seg.append(f"{line} {reg} {r.I_T:.2f}+-{r.sig_stat:.2f}(stat)+-{r.sig_cal:.2f}(cal+pb){' [blended with '+r.blend_with+' resp %.2f]'%r.blend_resp if r.blend_resp>0.05 else ''}")
    add(f'Unified per-line per-region integrated intensities, {ous} strong lines (beam aperture, template window)','; '.join(seg),'high','scripts/s12_line_table.py -> out/s12_line_table.csv',target=f'{ous}',unit='Jy/beam km/s',unc='see Band-6 entry')
# ---- 5. weak lines: replace round-1 entries with budgeted ones
for pre in ('SO 5_6-4_5','Unidentified feature','HC3N 28-27','CH3OH J_-1-J_0','HOC+ 2-1','H41beta','CH3CN 9-8','HC15N 4-3 integrated','SO 8_8-7_7 integrated','CS 7-6 integrated'):
    res[:]=drop(pre)
def S(ous,line,reg,key=None):
    r=row(ous,line,reg); return r
def fm(r): return f"{r.I_T:.3f}+-{r.sig_stat:.3f}(stat)+-{(r.sig_base if r.sig_base==r.sig_base else 0):.3f}(baseline)+-{r.sig_cal:.3f}(cal) [{r.snr:.1f} sigma]"+(f", 3sigma UL {r.UL3:.3f}" if r.UL3==r.UL3 else '')
def spv(l,reg,ous): x=spd.get((l,reg,ous)); return f"spatial test {x['snr_vs_field']:.1f} sigma (field MAD {x['field_sigma_MAD']:.3f}, {100*x['frac_pixels_above']:.2g}% of {x['n_pix']} field pixels >= value)" if x else 'spatial test n/a'
L='NS 11/2-9/2 f (253.968; "253.9 bump")'
hn,hs=S('Xb55','HOC+ 2-1','N'),S('Xb55','HOC+ 2-1','S'); hcn,hcs=S('Xb55','HCO+ 2-1','N'),S('Xb55','HCO+ 2-1','S')
add('HOC+ 2-1 (178.972 GHz) in Xb55 (8.6x5.9" beam; N and S unresolved: beam response of the other nucleus 0.7)',
    f"N-position aperture I={fm(hn)}; {spv('HOC+ 2-1','N','Xb55')}; S-position aperture I={fm(hs)}; {spv('HOC+ 2-1','S','Xb55')}. Both apertures are the same blended emission, so it is an N+S beam-integrated detection. I(HOC+)/I(HCO+ 2-1) = {hn.I_T/hcn.I_T:.4f}+-{hn.I_T/hcn.I_T*np.hypot(hn.sig_stat/hn.I_T,hcn.sig_stat/hcn.I_T):.4f} (N) and {hs.I_T/hcs.I_T:.4f}+-{hs.I_T/hcs.I_T*np.hypot(hs.sig_stat/hs.I_T,hcs.sig_stat/hcs.I_T):.4f} (S) => HCO+/HOC+ = {hcn.I_T/hn.I_T:.0f}+-{hcn.I_T/hn.I_T*np.hypot(hn.sig_stat/hn.I_T,hcn.sig_stat/hcn.I_T):.0f} / {hcs.I_T/hs.I_T:.0f}+-{hcs.I_T/hs.I_T*np.hypot(hs.sig_stat/hs.I_T,hcs.sig_stat/hcs.I_T):.0f} (line-intensity ratio, same beam; calibration cancels). Assignment: the only curated-list transition within +-0.1 GHz is HOC+ 2-1 (Eu 12.9 K); no species with Eu<300 K in the Splatalogue CDMS/JPL list used at 178.955-178.99 GHz; velocity (centre sys+4+-6 km/s in the round-1 free fit) and FWHM 133+-15 km/s agree with the region's HCO+ profile. Comparison (literature via web search snippets, papers not read in full; Sato+2022 could not be located): HCO+/HOC+ ~30-100 in the NGC 1068 circumnuclear disk (Usero+2004) and an HOC+/HCO+ column ratio ~0.04 at one position of NGC 3256 in Harada+2018 (HOC+ 1-0) - our line-intensity ratio 0.02-0.03 is the same order",
    'medium','scripts/s12_line_table.py, s12b_spatial_scatter.py -> out/s12_line_table.csv, s12b_spatial_scatter.json',target='N+S (Xb55)',unc='statistical + baseline in text; field (spatial) scatter 0.11 Jy/beam km/s (field median -0.05, a negative baseline bowl) => 9.5 sigma (N) and 6.8 sigma (S) vs field; calibration 10%; frequency-only assignment, single line',unit='Jy/beam km/s')
cn,cs=S('Xb55','CH3OH J-1-J0 E blend','N'),S('Xb55','CH3OH J-1-J0 E blend','S')
add('CH3OH J_-1-J_0 E series blend (J=1,2,3 at 165.050/165.061/165.099 GHz), Xb55 8.6x6.0"',
    f"N I={fm(cn)}; {spv('CH3OH J-1-J0 E blend','N','Xb55')}; S I={fm(cs)}; {spv('CH3OH J-1-J0 E blend','S','Xb55')}. Spw overlap check: the Xb55 spw20/22 frequency overlap (rest 166.08-166.66 GHz) does not contain CH3OH (obs 163.52-163.57 GHz is in spw22 only) so no independent-spw confirmation exists, but the overlap region itself is line-free and the two spws agree (difference mean -0.03/-0.07 mJy/beam, std 1.0/1.1 mJy vs rms 1.45/1.56 per channel at N/S, i.e. no baseline offset between basebands). Ladder check: J=4 (165.190) and J=5 (165.369) E lines are not seen (I_4=0.01+-0.04 N, 0.07+-0.05 S; I_5<0.13 (3 sigma)) => I(J=4)/I(J=1-3 blend)<0.15-0.17 (3 sigma) => optically thin LTE Trot < ~11-12 K, i.e. cold or sub-thermal CH3OH in the 9\" beam (NNLS of the five lines with the HCO+ profile template; J=1-3 are blended and degenerate). Competing species at 165.05: CH3OCH3 27(1,26)-27(2,25) Eu=363 K and HC5N J=62-61 Eu=250 K are not plausible",
    'high','scripts/s12_line_table.py, s12b_spatial_scatter.py, s16_b5_overlap.py, s17_ch3oh_ladder.py',target='N, S (Xb55)',unc='statistical+baseline; cal 10%; N/S blended (beam response 0.7-0.76): apertures are not independent',unit='Jy/beam km/s')
for reg,rr in (('N',S('Xb47','CS 7-6','N')),('S',S('Xb47','CS 7-6','S'))):
    bl=S('Xb47','H2CS 10(0,10)-9(0,9)',reg)
    add('CS 7-6 integrated intensity (template window, beam aperture, Xb47 4.3x2.8")',f"{fm(rr)}; the template fit at the H2CS 10_0,10-9_0,9 position (342.946) returns {bl.I_T:.2f}+-{bl.sig_stat:.2f}, but this is the same blended emission: CS 7-6 (342.883), H2CS (342.946) and 29SiO 8-7 (342.981) lie only 63-98 MHz = 55-86 km/s apart, less than the line width, so the detection is a blend of CS 7-6 with possible H2CS/29SiO; round-1 NNLS limits: H2CS <0.13-0.14, 29SiO <0.10 (3 sigma)",'high','out/s12_line_table.csv; s7d_blends.py',target=f'CS 7-6 {reg}',unc='blend-dominated systematic (CS vs H2CS/29SiO apportionment) not quantified beyond round-1 NNLS limits',unit='Jy/beam km/s')
so_f,so_d,so_b=S('Xb4f','SO 5_6-4_5','S'),S('Xb4d','SO 5_6-4_5','S'),S('Xb4b','SO 5_6-4_5','S')
add('SO 5_6-4_5 (251.826 GHz; the only SO line in Band 6 data)',
    f"UNCONFIRMED. Xb4f (5.7x3.5\") S: I={fm(so_f)}; {spv('SO 5_6-4_5','S','Xb4f')}; N {row('Xb4f','SO 5_6-4_5','N').I_T:.3f}+-{row('Xb4f','SO 5_6-4_5','N').sig_tot:.3f}. Also Bridge-position 3.3 sigma, E2-position 3.2 sigma in Xb4f (all within ~one 5.7\" beam of S: the same emission). Xb4d (0.94x0.74\") S: I={so_d.I_T:.3f}+-{so_d.sig_tot:.3f}, 3sigma UL {3*so_d.sig_tot:.3f}; spatial test at Xb4d {spv('SO 5_6-4_5','S','Xb4d')}; Xb4b S {so_b.I_T:.3f}+-{so_b.sig_tot:.3f}. If the Xb4f emission were smooth over >6\", beam dilution predicts only {so_f.I_T*0.93*0.74/(5.72*3.54):.3f} Jy/beam km/s at 0.94\" (below the 3 sigma Xb4d limit {3*so_d.sig_tot:.3f}) so the non-detection at 1\" and 0.25\" does NOT demonstrate an artefact, it is non-diagnostic; conversely the single-beam significance falls from 5.0 sigma (spectral) to 2.8 sigma against the spatial scatter of the field (1.6% of field pixels as high, max 0.48). Status: tentative at best; no use for shock diagnostics beyond the 3 sigma limits",
    'low','scripts/s12_line_table.py, s12b_spatial_scatter.py',target='S (Xb4f, Xb4d, Xb4b)',unc='stat+baseline in text; baseline-systematic 0.05-0.13 Jy/beam km/s at Xb4f (spectral vs spatial field scatter); cal 5%',unit='Jy/beam km/s')
b_f,b_d=S('Xb4f',L,'S'),S('Xb4d',L,'S'); e_f=S('Xb4f','NS 11/2-9/2 e (253.571)','S')
add('Unidentified feature at 253.85-254.15 GHz rest (nominal NS 11/2-9/2 Omega=1/2 f, 253.968 GHz)',
    f"UNCONFIRMED, probably a blend or baseline/extended-structure feature. Xb4f S: I={fm(b_f)}; vs spatial scatter of the field: {spv(L,'S','Xb4f')} (max field value 0.86); same feature at the Bridge position 4.7 sigma and at Sblue 4.4 sigma in Xb4f (one 5.7x3.5\" beam), N 1.2 sigma. Xb4d S {b_d.I_T:.3f}+-{b_d.sig_tot:.3f}; Xb4b S {S('Xb4b',L,'S').I_T:.3f}+-{S('Xb4b',L,'S').sig_tot:.3f}. Dilution estimate for a smooth source: Xb4d {b_f.I_T*0.93*0.74/(5.72*3.54):.3f}, so again non-diagnostic. Partner NS e component (253.571): Xb4f S {e_f.I_T:.3f}+-{e_f.sig_tot:.3f} (3sigma UL {3*e_f.sig_tot:.2f}; baseline scatter is 2x the statistical error there) - in LTE e/f ~1 would predict ~0.5, so the e-line limit does NOT exclude NS either (round-1 claim that the NS assignment is disfavoured at 5 sigma is withdrawn). Blends inside the 450 km/s-wide feature: SO2 253.957, c-HCCCH 254.013, SiS 14-13 254.103 (Xb4f S {S('Xb4f','SiS 14-13','S').I_T:.2f}+-{S('Xb4f','SiS 14-13','S').sig_tot:.2f}, 3.8 sigma). Not covered by any second independent spw (the Xb4f spw20 overlap with spw22 is only rest 253.10-253.18 GHz)",
    'low','scripts/s12_line_table.py, s12b_spatial_scatter.py',target='S (Xb4f)',unc='baseline systematic (spatial scatter) 0.13 Jy/beam km/s => 4 sigma, not 9.8',unit='Jy/beam km/s')
h_f,h_d,h_b=S('Xb4f','HC3N 28-27','N'),S('Xb4d','HC3N 28-27','N'),S('Xb4b','HC3N 28-27','N')
